{
    var trainer = sp.GetRequiredService<TicketModelTrainer>();
    trainer.TrainAndEvaluate();
}

var trainer2 = new TicketModelTrainer(
    builder.Services.BuildServiceProvider().GetRequiredService<ILogger<TicketModelTrainer>>(),
    builder.Services.BuildServiceProvider().GetRequiredService<IWebHostEnvironment>());

builder.Services.AddPredictionEnginePool<TicketData, TicketPrediction>()
    .FromFile(Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip"));

var app = builder.Build();
app.MapControllers();
app.Run();

